Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_show_list_empty_list(void) {
    // Setup: head is NULL to trigger the path where loop is not entered
    node *head = NULL;

    // Capture stdout to verify the function prints the header and nothing else
    stdout_capture_t *cap = capture_stdout_start();
    TEST_ASSERT_NOT_NULL(cap);

    // Test: call show_list with NULL head
    show_list(head);

    // Stop capture and get output
    char *output = capture_stdout_stop(cap);
    TEST_ASSERT_NOT_NULL(output);

    // Assertions: verify the output matches expected
    // The function prints the header line, then exits loop because head is NULL
    const char *expected = "Process Priority AT BT CT TAT WT 
";
    TEST_ASSERT_EQUAL_STRING(expected, output);

    // Cleanup
    free(output);
    // No need to free head because it's NULL
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_show_list_empty_list);
    return UNITY_END();
}

